<template>
  <d2-container>
    <div>
      <div>
        <el-button type="success" icon="el-icon-check" size="medium" @click="save"
          v-loading.fullscreen.lock="fullscreenLoading">保存</el-button>
        <el-button type="danger" icon="el-icon-back" size="medium" @click="xuqiu()">返回</el-button>
        <el-button type="primary" icon="el-icon-printer" size="medium" @click="djdy()">打印</el-button>
      </div>

      <el-card class="box-card" style="margin-top: 5px">
        <div slot="header" class="tb">
          <span>生成计划</span>
        </div>
        <div>
          <!-- <el-button type="primary" icon="el-icon-circle-plus-outline" plain size="small" class="xaa" @click="add">新增</el-button> -->
          <el-button type="success" icon="el-icon-document-copy" plain size="small" class="xaa" @click="dakai()">从商品库增加
          </el-button>
          <el-button type="danger" icon="el-icon-delete" plain size="small" class="xaa" @click="del">删除</el-button>
          <el-button type="primary" icon="el-icon-document-add" plain size="small" class="xaa" @click="xuqiu()">生成需求表
          </el-button>
          <vxe-table border resizable show-overflow show-footer ref="xTable" :loading="loading" :data="tableData"
            @cell-click="cellClickEvent" @edit-closed="gxsj" :edit-config="{ trigger: 'click', mode: 'cell' }">
            <vxe-column type="checkbox" width="50"></vxe-column>
            <vxe-column type="seq" width="60" title="序号"></vxe-column>
            <vxe-column field="客户ID" title="客户ID" width="80" :visible="false"></vxe-column>
            <vxe-column field="产品ID" title="产品ID" width="65"
              :content-render="{ name: 'input', attrs: { type: 'text' } }"></vxe-column>
            <vxe-column field="产品名称" title="产品名称" width="120"></vxe-column>
            <vxe-column field="型号" title="型号" :content-render="{ name: 'input', attrs: { type: 'text' } }"></vxe-column>
            <vxe-column field="规格" title="规格" :content-render="{ name: 'input', attrs: { type: 'text' } }"></vxe-column>
            <vxe-column field="单位" title="单位" :content-render="{ name: 'input', attrs: { type: 'text' } }"></vxe-column>
            <!-- <vxe-column field="单价" title="单价" :edit-render="{name: 'input', attrs: {type: 'text'}}" :edit-rules="{required:true}"></vxe-column> -->
            <vxe-column field="数量" title="生成数量" :edit-render="{ name: '$input', props: { type: 'number' } }"
              :edit-rules="{ required: true }"></vxe-column>
            <!-- <vxe-column field="金额" title="金额" >
          <template #default="{ row }">
              <span>{{row.单价 * row.数量}} </span>
            </template>
          </vxe-column> -->
          </vxe-table>
        </div>
      </el-card>
      <el-card class="box-card" style="margin-top: 5px">
        <div slot="header" class="tb">
          <span>原料需求</span>
        </div>
        <div>
          <vxe-table border resizable show-overflow show-footer ref="xTable2" :loading="loading" :data="tableData3"
            @cell-click="cellClickEvent" @edit-closed="gxsj2" :edit-config="{ trigger: 'click', mode: 'cell' }">
            <vxe-column type="checkbox" width="50"></vxe-column>
            <vxe-column type="seq" width="60" title="序号"></vxe-column>
            <vxe-column field="原料ID" title="产品ID" width="65"
              :content-render="{ name: 'input', attrs: { type: 'text' } }"></vxe-column>
            <vxe-column field="产品名称" title="产品名称" width="120"></vxe-column>
            <vxe-column field="型号" title="型号" :content-render="{ name: 'input', attrs: { type: 'text' } }"></vxe-column>
            <vxe-column field="规格" title="规格" :content-render="{ name: 'input', attrs: { type: 'text' } }"></vxe-column>
            <vxe-column field="单位" title="单位" :content-render="{ name: 'input', attrs: { type: 'text' } }"></vxe-column>
            <!-- <vxe-column field="单价" title="单价" :edit-render="{name: 'input', attrs: {type: 'text'}}" :edit-rules="{required:true}"></vxe-column> -->
            <vxe-column field="数量" title="需求数量" :edit-render="{ name: '$input', props: { type: 'number' } }"
              :edit-rules="{ required: true }"></vxe-column>
            <vxe-column field="总库存" title="库存数量" :edit-render="{ name: 'input', props: { type: 'number' } }"
              :visible="false"></vxe-column>
            <vxe-column field="预警数量" title="预警数量" :content-render="{ name: 'input', attrs: { type: 'number' } }">
            </vxe-column>
            <vxe-column field="采购数量" title="采购数量">
              <template #default="{ row }">
                <span>{{
                    Number(row.数量) + Number(row.预警数量) - Number(row.总库存)
                }}
                </span>
              </template>
            </vxe-column>
          </vxe-table>
        </div>
      </el-card>
      <!-- </div> -->
      <el-dialog :visible.sync="dialogTableVisible" title="商品信息">
        <el-input style="margin-left: 30px; width: 150px" size="medium" placeholder="输入商品名称" v-model="searchFilter.name"
          clearable></el-input>
        <el-button style="margin-left: 5px; margin-top: 10px" type="primary" icon="el-icon-search" size="medium" plain
          @click="handleSearch">搜索</el-button>
        <el-button style="margin-top: 10px" type="primary" icon="el-icon-zoom-out" size="medium" plain
          @click="clearFilter()">清空条件</el-button>
        <el-button v-if="$route.path == '/SpInfo'" type="info" icon="el-icon-download" size="medium"
          @click="exportDataEvent">导出</el-button>

        <vxe-table style="margin-top: 10px" border stripe resizable highlight-hover-row highlight-current-row
          align="center" @cell-dblclick="addduo()" :loading="loading" row-id="id" :print-config="{}" :data="tableData2"
          ref="xTable1" id="dy1">
          <vxe-table-column type="checkbox" width="60"></vxe-table-column>
          <vxe-table-column type="seq" width="50" title="序号"></vxe-table-column>
          <vxe-table-column field="id" title="id" :visible="false"></vxe-table-column>
          <vxe-table-column field="产品名称" title="产品名称"></vxe-table-column>
          <vxe-table-column field="产品ID" title="产品ID" width="80" :visible="false"></vxe-table-column>
          <vxe-table-column field="规格" title="规格"></vxe-table-column>
          <vxe-table-column field="型号" title="型号" width="80"></vxe-table-column>
          <vxe-table-column field="类型" title="类型"></vxe-table-column>
          <vxe-table-column field="单位" title="单位" width="80"></vxe-table-column>
          <vxe-table-column field="预警数量" title="预警数量"></vxe-table-column>
        </vxe-table>
        <vxe-pager :loading="loading" :current-page="tablePage.currentPage" :page-size="tablePage.pageSize"
          :total="tablePage.totalResult" :layouts="[
            'PrevPage',
            'JumpNumber',
            'NextPage',
            'FullJump',
            'Sizes',
            'Total',
          ]" @page-change="handlePageChange">
        </vxe-pager>

        <div slot="footer" class="dialog-footer">
          <el-button @click="dialogTableVisible = false">取 消</el-button>
          <el-button type="primary" @click="addduo()">确 定</el-button>
        </div>
      </el-dialog>
      <el-dialog :visible.sync="dialogTableVisible2" width="65%" @opened="printEvent">
        <div slot="title" class="dialog-footer">
          <el-button @click="dialogTableVisible2 = false">取 消</el-button>
          <el-button type="primary" @click="printEvent">打 印</el-button>
        </div>
        <div ref="print" id="myPrint5" media="print" style="font-family: \\5b8b\\4f53">
          <div v-for="(item, index) in tableData" :key="index" v-show="isShow">
            <div v-if="index % 3 == 0" ref="print2">
              <div style="width: 60%; margin: 0 auto; text-align: center">
                <h1 style="padding: 12px 0px 34px 0" id="djmz">采购单</h1>
                <!-- <div style='float:right;    font-size: 14px;font-weight: 800;'>页码:{{(index+3)/3}}/{{Math.ceil(tableData.length/3)}}</div> -->
              </div>

              <table border="0" style="width: 100%" id="printtable1">
                <tr height="30px;">
                  <td style="text-align: left">
                    入库单号：<span id="">{{ item.单据编号 }}</span>
                  </td>
                  <td style="text-align: center">
                    单位名称：<span id="">{{ dwmc }}</span>
                  </td>
                </tr>
              </table>
              <table border="1" style="
                  width: 100%;
                  display: inline-table;
                  border-collapse: collapse;
                " id="printtable2">
                <tr height="40px;">
                  <td style="text-align: center; width: 5%">序号</td>
                  <td style="text-align: center; width: 30%">商品名称</td>

                  <td style="text-align: center; width: 10%">规格</td>
                  <td style="text-align: center; width: 10%">型号</td>
                  <td style="text-align: center; width: 10%">数量</td>
                  <td style="text-align: center; width: 10%">单位</td>
                  <td style="text-align: center; width: 10%">单价</td>
                  <td style="text-align: center; width: 10%">金额</td>
                </tr>
                <tr height="40px;" v-for="(ite, ind) in tableData.slice(index, index + 3)" :key="ind">
                  <td style="text-align: center">{{ ind }}</td>
                  <td style="text-align: center">{{ ite.产品名称 }}</td>
                  <td style="text-align: center">{{ ite.规格 }}</td>
                  <td style="text-align: center">{{ ite.型号 }}</td>
                  <td style="text-align: center">{{ ite.数量 }}</td>
                  <td style="text-align: center">{{ ite.单位 }}</td>
                  <td style="text-align: center">{{ ite.单价 }}</td>
                  <td style="text-align: center">{{ ite.金额 }}</td>
                </tr>
              </table>
              <table border="0" style="width: 100%" id="printtable4">
                <tr height="30px;">
                  <td style="text-align: left">
                    页码:<span id="">{{ (index + 3) / 3 }}/{{
                        Math.ceil(tableData.length / 3)
                    }}</span>
                  </td>
                  <td style="text-align: center">
                    <span>总金额:￥{{ formData.zje }}元</span>
                  </td>
                  <!--  <td style='text-align:right;'><span></span></td> -->
                  <td style="text-align: right">
                    <span>总金额合计(大写):{{ jedx }}</span>
                  </td>
                </tr>
              </table>
              <table border="0" style="width: 100%" id="printtable3">
                <tr height="30px;">
                  <td style="text-align: left">
                    制单：<span id="">{{ yhmz }}</span>
                  </td>
                  <td style="text-align: center">
                    保管员：<span id="">{{ item.用户名 }}</span>
                  </td>
                  <td style="text-align: right">
                    入库日期：<span id="">{{ formData.date }}</span>
                  </td>
                </tr>
              </table>

              <div style="page-break-after: always"></div>
            </div>
          </div>
        </div>
      </el-dialog>
    </div>
  </d2-container>
</template>

<script>
import setter from "@/libs/setter.js";
import { Query, Aud } from "@api/shuju.js";
export default {
  name: "Xuqiu",
  components: {},
  data() {
    return {
      fullscreenLoading: false,
      loading: false,
      formData: {
        name: "",
        date: "",
        ddbh: "增加明细生成编号",
        fkfs: "",
        khmc: "",
        zje: "",
        djlx: "",
      },
      formRules: {
        khmc: [
          {
            required: true,
            message: "请输入客户名称",
          },
        ],
      },
      findList: [],
      fkfsList: [
        { value: "支付宝", label: "支付宝" },
        { value: "微信", label: "微信" },
        { value: "转账", label: "转账" },
        { value: "现金", label: "现金" },
      ],
      dialogTableVisible: false,
      dialogTableVisible2: false,
      isShow: true,
      dwmc: "",
      yhmz: "",
      jedx: "",
      fyjq: [],
      nameList: [],
      khList: [],
      cpList: [],
      yhList: [],
      kcList: [],
      tableData: [],
      tableData2: [],
      tableData3: [],
      nowView: 2,
      heji: [],
      authKeys: [],
      tablePage: {
        // 分页属性---
        currentPage: 1, //当前页 相当于layui的page
        pageSize: 10, //每页条数 相当于layui的limt
        totalResult: 0, //总页数   相当于count
      },
      //搜索变量
      searchFilter: {
        name: "",
        //account: '',
        disable: "",
      },
    };
  },
  props: {
    passID: Number,
    authKeys: String,
  },
  mounted() {
    this.checkDev();
    //this.InitRoles()
    this.getcpData();
    //this.InitCginfo()
    //this.getkhData()
    //this.getyhData()
    //this.getxuqiu()
    //this.getTableData()
  },
  methods: {
    back() {
      this.$emit("goBack");
    },
    checkDev() {
      this.isDev = process.env.NODE_ENV === "development" ? true : false;
    },
    exportDataEvent() {
      this.$refs.xTable.openExport();
    },
    sumNum(list, field) {
      let count = 0;
      let zje = 0;
      list.forEach((item) => {
        count += Number(item[field]);
        zje += Number(item["金额"]);
      });
      this.formData.zje = zje;
      console.log(this.formData.zje);
      return count;
    },

    footerMethod({ columns, data }) {
      const footerData = [
        columns.map((column, columnIndex) => {
          if (columnIndex === 0) {
            return "合计";
          }
          if (["数量", "金额"].includes(column.property)) {
            let zje = 0;
            let ndata = data.map(function (v, i) {
              let je = v.数量 * v.单价;
              return Object.assign(v, { 金额: je });
            });

            return this.sumNum(ndata, column.property);
          }

          return null;
        }),
      ];
      this.heji = footerData;
      return footerData;
    },
    add() {
      const $grid = this.$refs.xTable;
      $grid.insertAt({}, -1);

      let xsz = setter.getTime().split(" ");
      let xx = xsz[1].split(":"); //用split()函数将字符串分割成数组，（）里面的参数是分割条件;
      let xs = xsz[0].split("-"); //用split()函数将字符串分割成数组，（）里面的参数是分割条件;
      let bh = xs[0] + xs[1] + xs[2] + xx[0] + xx[1] + xx[2];
      this.formData.ddbh = "CGRK" + bh;
      this.formData.djlx = "采购入库";
    },
    del() {
      this.deleteInfo();
      /* const $grid = this.$refs.xTable
              $grid.removeCheckboxRow() */
    },
    addduo() {
      const $grid2 = this.$refs.xTable1;
      const $grid = this.$refs.xTable;
      let sj = $grid2.getCheckboxRecords().map(function (v, i) {
        delete v.id;
        delete v.日期;
        return v;
      });
      console.log(sj);
      $grid.insertAt(sj, -1);

      let xsz = setter.getTime().split(" ");
      let xx = xsz[1].split(":"); //用split()函数将字符串分割成数组，（）里面的参数是分割条件;
      let xs = xsz[0].split("-"); //用split()函数将字符串分割成数组，（）里面的参数是分割条件;
      let bh = xs[0] + xs[1] + xs[2] + xx[0] + xx[1] + xx[2];
      if (this.passID === "") {
        console.log(this.passID);
        this.formData.ddbh = "CGRK" + bh;
        this.formData.djlx = "采购入库";
        this.formData.date = xsz[0];
      }
      this.dialogTableVisible = false;
    },
    clearFilter() {
      let obj = this.searchFilter;
      for (let key in obj) {
        this.searchFilter;
        obj[key] = null;
      }
    },
    cellClickEvent({ column, row }) {
      /* console.log(`单元格点击${column.title}`)
              console.log(column.title)
              console.log(row) */
    },
    gxsj({ row, rowIndex, $rowIndex, column, columnIndex, $columnIndex }) {
      console.log(column.title);
      console.log(row);
      let bgsj = this.$refs.xTable.getTableData();
      console.log(bgsj);
      if (row.id) {
        let up = [{ id: row.id }];
        let jeobj;
        let upobj = { [column.title]: row[column.title] };
        if (upobj) {
          Object.assign(up[0], upobj);
        }
        if (["数量", "单价"].includes(column.title)) {
          jeobj = { 金额: row.单价 * row.数量 };
          Object.assign(up[0], jeobj);
        }
        console.log(up);
        Aud({
          reqType: "update",
          content: up,
          tablename: "订单",
        })
          .then((res) => {
            //this.fullscreenLoading = false
            this.$message.success("修改成功");
            //	this.$emit('goBack')
          })
          .catch((err) => {
            //this.fullscreenLoading = false
          });
      } else {
      }
    },
    xuqiu() {
      let bsj = this.$refs.xTable.getTableData();
      let sqyj;
      let fzsq = "";
      let sql2;

      if (bsj.tableData.length == 0) {
        this.$message.error("请先选择产品");
      } else if (bsj.tableData.length > 0) {
        for (let i = 0; i < bsj.tableData.length; i++) {
          if (!bsj.tableData[i].数量) {
            this.$message.error("请填写数量");
          } else {
            if (bsj.tableData.length > 0) {
              fzsq += `SELECT 产品ID,原料ID,SUM(数量)*${bsj.tableData[i].数量} AS 总数 FROM bom  WHERE 产品ID IN ('${bsj.tableData[i].产品ID}') GROUP BY 原料ID UNION  ALL  `;
              //  /(.*)UNION  ALL/ 匹配最后一个字符串的方法
              // fzsq.replace(/(.*)UNION  ALL/,'$1') 匹配最后一个字符串，并替换成空格
              sql2 = `CREATE TEMPORARY TABLE ls AS
                                  (
                               ${fzsq.replace(/(.*)UNION  ALL/, "$1")}     
                                  );`;
            }
          }
        }
      }
      console.log(sql2);
      //fzsq = fzsq.replace(/(.*)UNION/,'');
      // console.log(fzsq.replace(/(.*)UNION  ALL/,'$1'))
      //console.log(/UNION$/.exec(fzsq))
      let sql = `DROP TABLE  IF  EXISTS ls;`;

      let sql3 = `SELECT  ls.原料ID,产品.产品名称,产品.规格,产品.型号,产品.预警数量,a.总库存,SUM(总数) AS 数量 FROM ls INNER JOIN 产品 ON ls.原料ID=产品.产品ID  INNER JOIN (SELECT id,产品ID, IFNULL(SUM(库存数量),0) AS 总库存 FROM 查询库存 GROUP BY 产品ID )AS a ON ls.原料ID=a.产品ID GROUP BY ls.原料ID`;
      this.loading = true;
      //this.getkcData()
      Query({
        content: sql,
        tj: "for",
      })
        .then((res) => {
          if (!res.data.message) {
            Query({
              content: sql2,
              tj: "for",
            })
              .then((res2) => {
                if (res2.data.message) {
                  Query({
                    content: sql3,
                    tj: "for",
                  })
                    .then((res3) => {
                      this.tableData3 = res3.data;

                      this.loading = false;
                    })
                    .catch((err) => {
                      // 异常情况
                      this.loading = false;
                    });
                }
              })
              .catch((err) => {
                // 异常情况
                this.loading = false;
              });
          }
        })
        .catch((err) => {
          // 异常情况
          this.loading = false;
        });
    },
    getkcData() {
      let sql6 = `SELECT id,产品ID,产品名称,规格,型号,单位,预警数量, IFNULL(SUM(库存数量),0) AS 总库存 FROM 查询库存`;
      Query({
        //limit: this.tablePage.pageSize,
        //page: this.tablePage.currentPage,
        tj: `库存数量 >= 0` + `  GROUP BY 产品ID `,
        content: sql6,
        field: "id",
      })
        .then((res) => {
          //let _this = this
          /* let cpsj = _this.cplist
              let ss = res.data.map(function(v,i) {
            let obj4 = cpsj.find(o => o.产品ID === v.产品ID); 
            delete obj4.id;
            delete obj4.日期;
          	
             return   Object.assign(v,obj4);						
            });	
          	
            console.log(ss)  */

          this.kcList = res.data;

          //	this.tablePage.totalResult = res.count
          this.loading = false;
        })
        .catch((err) => {
          // 异常情况
          this.loading = false;
        });
    },
    getkhData() {
      Query({
        tj: `启用 = -1 `,
        tablename: "客户",
        field: "id",
      })
        .then((res) => {
          this.khList = res.data;
          /* let khsj = res.data.map(function(v,i){
                 return  { value: v.客户ID, label:v.客户名称 } 
              })
              this.khList = khsj		*/
        })
        .catch((err) => {
          // 异常情况
        });
    },
    getyhData() {
      Query({
        tj: `用户名 is not null `,
        tablename: "用户",
        field: "id",
      })
        .then((res) => {
          //this.tableData = res.data()
          let yhsj = res.data.map(function (v, i) {
            return { value: v.用户名, label: v.用户名 };
          });
          this.yhList = yhsj;
        })
        .catch((err) => {
          // 异常情况
        });
    },
    getcpData() {
      Query({
        tj: true,
        tablename: "产品",
        field: "id",
      })
        .then((res) => {
          //this.tableData = res.data()
          //console.log(res.data)
          this.cpList = res.data;
        })
        .catch((err) => {
          // 异常情况
        });
    },
    getTableData() {
      let tjx;
      this.loading = true;
      if (this.searchFilter.name != "" && this.searchFilter.name != null) {
        tjx = `产品名称 like '%${this.searchFilter.name}%'`;
        //tj += ' and ' + tjx
      } else {
        tjx = true;
        //tj += ' and ' + tjx
      }

      Query({
        limit: this.tablePage.pageSize,
        page: this.tablePage.currentPage,
        tj: tjx,
        tablename: "产品",
