        Query({
          tablename: "采购",
          field: "id",
          tj: `id= '${this.passID}' `,
        })
          .then((res) => {
            console.log(res.data);
            this.formData.name = res.data[0].用户名;
            this.formData.date = res.data[0].日期;
            this.formData.ddbh = res.data[0].单据编号;
            this.formData.fkfs = res.data[0].付款方式;
            this.formData.khmc = res.data[0].客户ID;
            this.formData.zje = res.data[0].总金额;
            this.formData.djlx = res.data[0].类型;

            Query({
              tablename: "订单",
              field: "id",
              tj: `单据编号 = '${res.data[0].单据编号}'`,
            })
