      let selectRecords = this.$refs.xTable.getCheckboxRecords();
      let tempIDs = [];
      for (let i = 0; i < selectRecords.length; i++) {
        let sr = selectRecords[i];
        if (sr.id) {
          tempIDs.push(sr.id);
        } else {
          this.$confirm("确定要永久删除?", "提示", {
            confirmButtonText: "确定",
            cancelButtonText: "取消",
            type: "warning",
          })
            .then(() => {
              const $grid = this.$refs.xTable;
              $grid.removeCheckboxRow();
              this.InitCginfo();
            })
            .catch(() => { });
        }
      }
      console.log(tempIDs);
      if (tempIDs.length > 0) {
        this.$confirm("确定要永久删除?", "提示", {
          confirmButtonText: "确定",
          cancelButtonText: "取消",
          type: "warning",
        })
          .then(() => {
